from hermes_tools import terminal
r=terminal("python3 - <<'PY'
P={'C':[(0,0),(0,11),(1,4),(2,7),(5,15)],'U':[(3,1),(3,13),(4,10),(5,6)]}
for metric, fn in [('L1',lambda a,b:abs(a[0]-b[0])+abs(a[1]-b[1])),('Linf',lambda a,b:max(abs(a[0]-b[0]),abs(a[1]-b[1]))),('L2sq',lambda a,b:(a[0]-b[0])**2+(a[1]-b[1])**2)]:
 print('METRIC',metric)
 for label in ['C','U']:
  for p in P[label]:
   others=[(fn(p,q), lab,q) for lab,pts in P.items() for q in pts if q!=p]
   d=min(x[0] for x in others)
   print(label,p,'nearest',[(lab,q) for x,lab,q in others if x==d],d,'within same',min(fn(p,q) for q in P[label] if q!=p))
print('modular columns')
for m in range(2,9):
 c=[x[1]%m for x in P['C']]; u=[x[1]%m for x in P['U']]
 if not set(c)&set(u): print(m,'perfect separated',set(c),set(u))
PY")
print(r['output'])

